/** Material Symbols are drawn on a 960 grid whose top is at -960. */
private fun symbol(name: String, vararg paths: String): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 960f, 960f).apply {
        group(translationY = 960f) {
            for (d in paths) addPath(pathData = addPathNodes(d), fill = SolidColor(Color.Black))
        }
    }.build()
